def _need(condition, code):
    if not condition:
        raise ValueError(code)


def _pin(raw):
    _need(type(raw) is bytes, 'exact-bytes-required')
    return len(raw), hashlib.sha256(raw).hexdigest()


def _expect(raw, expected):
    _need(_pin(raw) == expected, 'fixed-full-source-pin')
    return raw


def _edits(raw, changes, inverse=False):
    spans = []
    for name, old, new in (reversed(changes) if inverse else changes):
        if inverse:
            old, new = new, old
        _need(raw.count(old) == 1, 'closed-literal-count:' + name)
        if not inverse:
            _need(new not in raw, 'closed-new-literal-absent:' + name)
        start = raw.find(old)
        spans.append({'name': name, 'start': start, 'old_bytes': len(old), 'new_bytes': len(new), 'end_exclusive': start + len(old)})
        raw = raw.replace(old, new, 1)
    return raw, spans


def _worker_edits(prefix_new):
    return WORKER_FIXED + (('refresh-prefix-pin', PREFIX_OLD, prefix_new),)


def _patch_worker(worker):
    mid, spans = _edits(worker, WORKER_FIXED)
    delta = len(mid) - len(worker)
    prefix_len = ORIGINAL_PREFIX + delta
    literal_at = mid.find(PREFIX_OLD)
    _need(literal_at == worker.find(PREFIX_OLD) + delta, 'prefix-literal-shift')
    _need(literal_at > prefix_len, 'prefix-literal-after-prefix')
    _need(spans[0]['start'] < ORIGINAL_PREFIX, 'drain-methods-inside-prefix')
    _need(spans[1]['start'] < prefix_len, 'fetch-branch-inside-prefix')
    digest = hashlib.sha256(mid[:prefix_len]).hexdigest()
    prefix_new = ("prefixBytes:%d,prefixSha256:'%s'" % (prefix_len, digest)).encode()
    if PREFIX_NEW is not None:
        _need(prefix_new == PREFIX_NEW, 'predicted-prefix-pin')
    patched, more = _edits(mid, (('refresh-prefix-pin', PREFIX_OLD, prefix_new),))
    _need(hashlib.sha256(patched[:prefix_len]).hexdigest() == digest, 'prefix-pin-stable')
    _need(SUCCESS_TAIL in patched and OLD_THROW not in patched, 'success-tail-retained')
    return patched, spans + more, prefix_new, prefix_len, digest


def _proxy_edit(worker):
    pin = _pin(worker)
    old = PROXY_PIN_OLD
    new = ("'ThreadEventHandler.js':(%d,'%s')" % pin).encode()
    _need(new != old, 'worker-pin-must-change')
    return (('retarget-worker-pin', old, new),), new, pin


def _proof(worker, controller, proxy, spans, prefix_len, prefix_digest):
    return {
        'schema': 't10.005.negative-lifecycle-source-patch.v1',
        'source_only': True,
        'runtime_admitted': False,
        'admission_ready': False,
        'root5_immutable': True,
        'prior_normal_or_geometry_qualification_covers_changed_worker': False,
        'trace_is_grant': False,
        'launcher_join': 'independent-required',
        'failure_limit_ms': 5000,
        'failure_limit_basis': 'proxy connection and upstream read settimeout(5) seconds; local failure limit only',
        'canonical_negative_body_bytes': 14,
        'input_pins': {role: {'bytes': length, 'sha256': digest} for role, (length, digest) in INPUT_PINS.items()},
        'output_pins': {
            'worker': {'bytes': len(worker), 'sha256': hashlib.sha256(worker).hexdigest()},
            'controller': {'bytes': len(controller), 'sha256': hashlib.sha256(controller).hexdigest()},
            'proxy': {'bytes': len(proxy), 'sha256': hashlib.sha256(proxy).hexdigest()},
        },
        'prefix': {'bytes': prefix_len, 'sha256': prefix_digest, 'original_bytes': ORIGINAL_PREFIX, 'original_sha256': ORIGINAL_PREFIX_SHA},
        'literal_edit_counts': {'worker': 3, 'controller': len(CONTROLLER_FIXED), 'proxy': 1},
        'spans': spans,
        'preserved': {
            'native_manifest_loop_unchanged': True,
            'static_names': 6,
            'protected_roles': 9,
            'node_source_roles': 7,
            'original_G_and_shared_120s': True,
        },
        'downstream_pin_updates': list(DOWNSTREAM),
        'inverse': 'Reverse the recorded literal pairs from last to first, then require the original full pins.',
        'all_full_inverses_required': True,
    }


def apply_quest_negative_lifecycle_patch(worker, controller, proxy):
    """Return three inert byte bodies plus exact literal, prefix, and inverse proof."""
    original = {'worker': worker, 'controller': controller, 'proxy': proxy}
    for role, raw in original.items():
        _expect(raw, INPUT_PINS[role])
    patched_worker, worker_spans, prefix_new, prefix_len, prefix_digest = _patch_worker(worker)
    proxy_changes, _proxy_new, _worker_pin = _proxy_edit(patched_worker)
    patched_proxy, proxy_spans = _edits(proxy, proxy_changes)
    patched_controller, controller_spans = _edits(controller, CONTROLLER_FIXED)
    result = {'worker': patched_worker, 'controller': patched_controller, 'proxy': patched_proxy}
    if PREDICTIONS is not None:
        for role, expected in PREDICTIONS.items():
            _expect(result[role], expected)
    spans = (
        [dict(span, role='worker', coordinate_basis='role-bytes-before-this-forward-edit') for span in worker_spans]
        + [dict(span, role='controller', coordinate_basis='role-bytes-before-this-forward-edit') for span in controller_spans]
        + [dict(span, role='proxy', coordinate_basis='role-bytes-before-this-forward-edit') for span in proxy_spans]
    )
    proof = _proof(patched_worker, patched_controller, patched_proxy, spans, prefix_len, prefix_digest)
    result['proof'] = proof
    _need(inverse_quest_negative_lifecycle_patch(result) == original, 'full-source-inverse')
    for role, markers in PRESERVED.items():
        for marker in markers:
            _need(marker in original[role] and marker in result[role], 'preserved-marker:' + role)
    return result


def inverse_quest_negative_lifecycle_patch(patched):
    """Reverse fixed output bodies; supplied proof metadata is not authority."""
    _need(type(patched) is dict and set(patched) == {'worker', 'controller', 'proxy', 'proof'}, 'closed-output-roles')
    _need(type(PREDICTIONS) is dict and set(PREDICTIONS) == {'worker', 'controller', 'proxy'}, 'fixed-output-predictions-required')
    for role in ('worker', 'controller', 'proxy'):
        _expect(patched[role], PREDICTIONS[role])
    worker = patched['worker']
    _need(type(PREFIX_NEW) is bytes and worker.count(PREFIX_NEW) == 1 and worker.count(b"prefixBytes:") == 1 and PREFIX_OLD not in worker, 'patched-prefix-literal')
    prefix_at = worker.find(b"prefixBytes:")
    _need(prefix_at > ORIGINAL_PREFIX, 'inverse-prefix-site')
    line_end = worker.find(b",\n    hooks:", prefix_at)
    _need(line_end > prefix_at, 'inverse-prefix-shape')
    prefix_literal = worker[prefix_at:line_end]
    _need(prefix_literal == PREFIX_NEW, 'inverse-prefix-literal')
    worker, _spans = _edits(worker, _worker_edits(prefix_literal), inverse=True)
    _expect(worker, INPUT_PINS['worker'])
    _pin_worker = _pin(patched['worker'])
    proxy_new = ("'ThreadEventHandler.js':(%d,'%s')" % _pin_worker).encode()
    proxy, _spans = _edits(patched['proxy'], (('retarget-worker-pin', PROXY_PIN_OLD, proxy_new),), inverse=True)
    controller, _spans = _edits(patched['controller'], CONTROLLER_FIXED, inverse=True)
    result = {'worker': worker, 'controller': controller, 'proxy': proxy}
    for role, raw in result.items():
        _expect(raw, INPUT_PINS[role])
    return result
